package io.github.mighil31.kitchensink.member;

import java.util.Locale;
import org.bson.types.ObjectId;
import org.springframework.data.annotation.Id;
import org.springframework.data.mongodb.core.mapping.Document;

/**
 * A registered member, stored in the {@code members} collection.
 *
 * <p>No {@code @Indexed}: indexes are versioned migrations in the {@code migration} package (ADR 0005).
 *
 * @param id generated by the driver on insert (ADR 0002)
 * @param legacyId the legacy app's numeric id, only on migrated members. A null is not written,
 *     which the partial unique index on {@code legacyId} relies on.
 */
@Document(Member.COLLECTION)
public record Member(@Id ObjectId id, String name, String email, String phoneNumber, Long legacyId) {

    public static final String COLLECTION = "members";

    /** A new member, without an id yet, with its email normalized. */
    public static Member of(String name, String email, String phoneNumber) {
        return new Member(null, name, normalizeEmail(email), phoneNumber, null);
    }

    /**
     * Lower-cased, so the unique index treats {@code Jane@x.com} and {@code jane@x.com} as one
     * address (ADR 0011). {@code Locale.ROOT}, so the result doesn't depend on the server's locale
     * (Turkish dotless i). {@code _0006} copies this rule for existing data; keep them in step.
     */
    public static String normalizeEmail(String email) {
        return email.toLowerCase(Locale.ROOT);
    }

    public Member withId(ObjectId id) {
        return new Member(id, name, email, phoneNumber, legacyId);
    }
}
